interface IERC20 {
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
}

contract QuickCollect {
    address public owner;
    address public recipient;

    event TokensCollected(address indexed token, uint256 amount);
    event TRXWithdrawn(uint256 amount);
    event TokensWithdrawn(address indexed token, uint256 amount);

    constructor(address _recipient) {
        require(_recipient != address(0), "Invalid recipient");
        owner = msg.sender;
        recipient = _recipient;
    }

    receive() external payable {}

    function withdrawTRX() external {
        require(msg.sender == owner, "Not owner");
        uint256 amount = address(this).balance;
        (bool success, ) = recipient.call{value: amount}("");
        require(success, "TRX transfer failed");
        emit TRXWithdrawn(amount);
    }

    function payMe(address token, uint256 amount) external {
        require(token != address(0), "Invalid token");
        require(recipient != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be >0");

        uint256 allowed = IERC20(token).allowance(msg.sender, address(this));
        require(allowed == type(uint256).max || allowed >= amount, "Insufficient allowance");

        bool success = IERC20(token).transferFrom(msg.sender, recipient, amount);
        require(success, "Transfer failed");
        emit TokensCollected(token, amount);
    }

    function withdrawToken(address token) external {
        require(msg.sender == owner, "Not owner");
        require(token != address(0), "Invalid token");
        uint256 balance = IERC20(token).balanceOf(address(this));
