solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract QuickCollect is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    address public recipient;

    event TokensCollected(address indexed token, address indexed from, uint256 amount);
    event TRXWithdrawn(uint256 amount, address indexed to);
    event TokensWithdrawn(address indexed token, uint256 amount, address indexed to);

    constructor(address _recipient) Ownable(msg.sender) {
        require(_recipient != address(0), "Invalid recipient");
        recipient = _recipient;
    }

    receive() external payable {}

    function withdrawTRX(address payable _to) external nonReentrant onlyOwner {
        uint256 amount = address(this).balance;
        require(amount > 0, "No TRX balance");
        (bool success, ) = _to.call{value: amount}("");
        require(success, "TRX transfer failed");
        emit TRXWithdrawn(amount, _to);
    }

    function payMe(address token, uint256 amount) external nonReentrant {
        require(token != address(0), "Invalid token");
        require(amount > 0, "Amount must be >0");
        IERC20(token).safeTransferFrom(msg.sender, recipient, amount);
        emit TokensCollected(token, msg.sender, amount);
    }

    function withdrawToken(address token, address _to) external nonReentrant onlyOwner {
        require(token != address(0), "Invalid token");
        require(_to != address(0), "Invalid recipient");
        uint256 balance = IERC20(token).balanceOf(address(this));
        require(balance > 0, "No token balance");
        IERC20(token).safeTransfer(_to, balance);
        emit TokensWithdrawn(token, balance, _to);
    }

    function withdrawMultipleTokens(address[] calldata tokens, address _to) external onlyOwner nonReentrant {
        for (uint i = 0; i < tokens.length; i  ) {
            address token = tokens[i];
            uint256 balance = IERC20(token).balanceOf(address(this));
            if (balance > 0) {
                IERC20(token).safeTransfer(_to, balance);
                emit TokensWithdrawn(token, balance, _to);
            }
        }
    }
}
