solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./QuickCollect.sol";
import "./TestToken.sol";

contract TestQuickCollect {
    QuickCollect public quickCollect;
    TestToken public testToken;
    address public owner;
    address public recipient = 0xAb8483F64d9C6d1EcF9b849Ae677dD3315835cb2;

    event LogSuccess(string message);
    event LogFailure(string message, string reason);

    constructor() {
        owner = msg.sender;
        quickCollect = new QuickCollect(recipient);
        testToken = new TestToken(owner);
    }

    function testPayMe() public {
        testToken.mint(owner, 1000 * 10**18);
        testToken.approve(address(quickCollect), 100 * 10**18);
        quickCollect.payMe(address(testToken), 100 * 10**18);

        require(testToken.balanceOf(recipient) == 100 * 10**18, "PayMe failed");
        emit LogSuccess("testPayMe passed");
    }

    function testPayMeWithZeroAmount() public {
        testToken.mint(owner, 1000 * 10**18);
        testToken.approve(address(quickCollect), 100 * 10**18);

        try quickCollect.payMe(address(testToken), 0) {
            revert("Should have failed");
        } catch Error(string memory reason) {
            require(keccak256(bytes(reason)) == keccak256(bytes("Amount must be >0")));
            emit LogSuccess("testPayMeWithZeroAmount passed");
        }
    }

    function testInsufficientAllowance() public {
        testToken.mint(owner, 1000 * 10**18);
        testToken.approve(address(quickCollect), 50 * 10**18);

        try quickCollect.payMe(address(testToken), 100 * 10**18) {
            revert("Should have failed");
        } catch Error(string memory reason) {
            require(keccak256(bytes(reason)) == keccak256(bytes("Insufficient allowance")));
            emit LogSuccess("testInsufficientAllowance passed");
        }
    }

    function testWithdrawTRX() public {
        payable(address(quickCollect)).transfer(1 ether);
        require(address(quickCollect).balance == 1 ether, "Deposit failed");

        quickCollect.withdrawTRX(payable(owner));
        require(address(quickCollect).balance == 0, "Withdraw failed");

        emit LogSuccess("testWithdrawTRX passed");
    }

    function runAllTests() public {
        testPayMe();
        testPayMeWithZeroAmount();
        testInsufficientAllowance();
        testWithdrawTRX();
        emit LogSuccess("All tests passed!");
    }
}
