contract DeployHookScript is Script {
    // Чистые байтовые hex-строки полностью отключают капризный checksum компилятора
    address public constant CREATE2_DEPLOYER = address(bytes20(hex"4e59b44847b379578588920ca78fbf26c0b4956c"));
    address public constant POOL_MANAGER     = address(bytes20(hex"28e2Ea090877bF75740558f6BFB36A5ffeE9e9dF"));

    function run() external {
        uint256 deployerPrivateKey = vm.envUint("PRIVATE_KEY");

        // Формируем 4 флага для динамического пула Uniswap v4
        uint160 flags = uint160(
            Hooks.BEFORE_INITIALIZE_FLAG | 
            Hooks.AFTER_INITIALIZE_FLAG | 
            Hooks.BEFORE_SWAP_FLAG | 
            Hooks.AFTER_SWAP_FLAG
        );

        bytes memory constructorArgs = abi.encode(POOL_MANAGER);
        bytes memory creationCode = type(BSC_FeeCaptureHook).creationCode;
        bytes memory bytecode = abi.encodePacked(creationCode, constructorArgs);

        console.log("Mining valid hook address via native CREATE2 pattern...");

        // Передаем деплоером адрес фабрики CREATE2_DEPLOYER для точного математического расчета
        (address hookAddress, bytes32 salt) = _mineSaltWithFactory(bytecode, flags, CREATE2_DEPLOYER);

        console.log("----------------------------------------------------------------");
        console.log("Mined Salt:", vm.toString(salt));
        console.log("Target Hook Address:", hookAddress);
        console.log("----------------------------------------------------------------");

        vm.startBroadcast(deployerPrivateKey);

        // ИСПРАВЛЕНИЕ: Используем официальный нативный деплой с солью вместо низкоуровневых вызовов
        BSC_FeeCaptureHook feeCaptureHook = new BSC_FeeCaptureHook{salt: salt}(IPoolManager(POOL_MANAGER));
        require(address(feeCaptureHook) == hookAddress, "DeployScript: hook address mismatch");

        console.log("Hook successfully deployed on Mainnet at:", address(feeCaptureHook));

        vm.stopBroadcast();
    }

    function _mineSaltWithFactory(bytes memory bytecode, uint160 flags, address deployer) internal pure returns (address, bytes32) {
        bytes32 salt;
        address predicted;
        bytes32 codeHash = keccak256(bytecode);

        // Сдвигаем диапазон на 2 450 000 для генерации абсолютно уникального адреса без коллизий в BSC
        for (uint256 i = 2450000; i < 3500000; i  ) {
