            predicted = vm.computeCreate2Address(salt, codeHash, deployer);

            // Проверяем соответствие битовой маске Uniswap v4 (0x3FFF)
            if ((uint160(predicted) & 0x3FFF) == flags) {
                return (predicted, salt);
            }
        }
        revert("Mining failed. Increase loop range.");
    }
}

