contract DigitalProof {
    // 存证结构体：单条存证记录的完整信息
    struct Proof {
        string fileHash;     // 文件哈希值（如 SHA256），唯一标识文件
        string description;  // 文件描述，如“论文初稿”“合同扫描件”
