    mapping(string => Proof) public proofs;

    // 辅助映射：地址 -> 该地址的存证数量（可选，用于统计）
    mapping(address => uint256) public userProofCount;

    // ------------------------------
    // 事件定义（链上日志，可被前端监听）
    // ------------------------------
    /// @notice 存证成功事件
    event ProofStored(
        string indexed fileHash,
        address indexed owner,
        string description,
        uint256 timestamp
    );

    /// @notice 存证所有权转让事件
