     * @dev 查询单条存证的完整信息
     * @param _fileHash 要查询的文件哈希值
     * @return fileHash 文件哈希、description 描述、owner 所有者、timestamp 时间戳
     */
    function getProof(string memory _fileHash) public view returns (
        string memory fileHash,
        string memory description,
        address owner,
        uint256 timestamp
    ) {
        Proof memory p = proofs[_fileHash];
        // 校验：存证必须存在
        require(p.timestamp != 0, "Proof does not exist");
        return (p.fileHash, p.description, p.owner, p.timestamp);
    }

    /**
     * @dev 验证文件是否已被存证
     * @param _fileHash 要验证的文件哈希值
     * @return bool 存证存在返回 true，否则 false
     */
    function verifyProof(string memory _fileHash) public view returns (bool) {
        return proofs[_fileHash].timestamp != 0;
    }

    /**
     * @dev 转让存证的所有权（模拟版权/文件归属权转移）
     * @param _fileHash 要转让的文件哈希值
     * @param _newOwner 接收方地址
     */
    function transferProof(string memory _fileHash, address _newOwner) public {
        Proof storage p = proofs[_fileHash];

        // 校验：存证必须存在
        require(p.timestamp != 0, "Proof does not exist");
        // 校验：调用者必须是当前所有者
        require(p.owner == msg.sender, "You are not the owner of this proof");
        // 校验：接收方地址不能为0地址（避免无效转让）
        require(_newOwner != address(0), "Cannot transfer to zero address");
        // 校验：不能转让给自己
        require(_newOwner != msg.sender, "Cannot transfer to yourself");

        // 更新存证所有者
        address oldOwner = p.owner;
        p.owner = _newOwner;

        // 更新双方的存证数量统计
        userProofCount[oldOwner]--;
        userProofCount[_newOwner]  ;

        // 触发转让事件
        emit ProofTransferred(_fileHash, oldOwner, _newOwner);
    }

    /**
     * @dev 查询当前调用者的存证总数
     * @return uint256 存证数量
     */
    function getMyProofCount() public view returns (uint256) {
        return userProofCount[msg.sender];
    }
