    event CardListed(uint256 indexed listingId, uint256 indexed tokenId, address indexed seller, uint256 price);
    event CardSold(uint256 indexed listingId, uint256 indexed tokenId, address indexed buyer, address seller, uint256 price);
    event CardListingCanceled(uint256 indexed listingId);

    modifier noReentrant() {
        require(!locked, "No simultaneous calls allowed");
        locked = true;
        _;
        locked = false;
    }

    constructor(address _nftContractAddress) {
        require(_nftContractAddress != address(0), "Invalid NFT contract address");
        owner = msg.sender;
        nftContractAddress = _nftContractAddress;
    }

    // 1. LIST CARD
    function listCard(uint256 _tokenId, uint256 _price) external {
        IERC721Native nft = IERC721Native(nftContractAddress);
        require(nft.ownerOf(_tokenId) == msg.sender, "Not the card owner");
        require(nft.isApprovedForAll(msg.sender, address(this)), "Marketplace not approved");
        require(_price > 0, "Price must be greater than zero");

        listingCounter  ;
        listings[listingCounter] = Listing(listingCounter, _tokenId, payable(msg.sender), _price, true);

        emit CardListed(listingCounter, _tokenId, msg.sender, _price);
    }

    // 2. BUY CARD
    function buyCard(uint256 _listingId) external payable noReentrant {
        require(_listingId > 0 && _listingId <= listingCounter, "Listing does not exist");
        Listing storage listing = listings[_listingId];
        require(listing.isActive, "Listing is not active");
        require(msg.value >= listing.price, "Insufficient funds sent");

        listing.isActive = false; 

        IERC721Native(nftContractAddress).safeTransferFrom(listing.seller, msg.sender, listing.tokenId);

        uint256 feeAmount = (listing.price * feePercentage) / 10000;
        uint256 sellerAmount = listing.price - feeAmount;

        (bool successOwner, ) = payable(owner).call{value: feeAmount}("");
        require(successOwner, "Fee payout failed");

        (bool successSeller, ) = listing.seller.call{value: sellerAmount}("");
        require(successSeller, "Seller payout failed");

        emit CardSold(_listingId, listing.tokenId, msg.sender, listing.seller, listing.price);
    }

    // 3. CANCEL LISTING
    function cancelListing(uint256 _listingId) external noReentrant {
        require(_listingId > 0 && _listingId <= listingCounter, "Listing does not exist");
        Listing storage listing = listings[_listingId];
        require(listing.seller == msg.sender, "Not the seller");
        require(listing.isActive, "Listing is not active");

        listing.isActive = false;

        emit CardListingCanceled(_listingId);
    }
}

